def recover_cards(n, d, l):
    if n == 2:
        if d < 0 or d > l:
            return [-1]
        return [l, l + d]

    if n == 3:
        if d < 0 or d > l:
            return [-1]
        return [l, 1, l + d]

    if n == 4:
        if d < 0 or d > l:
            return [-1]
        return [l, 1, 1, l + d]

    if n == 5:
        if d < 0 or d > l:
            return [-1]
        return [l, 1, 1, 1, l + d]

    # For n >= 6, we can always construct a valid sequence
    if d < 0 or d > l:
        return [-1]

    result = [l] * (n - 1)
    result.append(l + d)
    return result

